-- PT112-S3-Q5. Batch 11.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT112-S3-Q5$batch11$ AND q.stimulus=$batch11$Solicitor: Loux named Zembaty executor of her will. Her only beneficiary was her grandson, of whom she was very fond. Prior to distributing the remainder to the beneficiary, Zembaty was legally required to choose which properties in the estate should be sold to clear the estate’s heavy debts. Loux never expressed any particular desire about the Stoke Farm, which includes the only farmland in her estate. Thus, it is unlikely that Loux would have had any objection to Zembaty’s having sold it rather than having transferred it to her grandson.$batch11$ AND q.prompt=$batch11$Which one of the following, if true, most weakens the solicitor's argument?$batch11$ AND q.correct_choice=$batch11$E$batch11$) THEN RAISE EXCEPTION 'Question changed: PT112-S3-Q5'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch11$PT112-S3-Q5$batch11$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT112-S3-Q5'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT112-S3-Q5$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Conclusion$batch11$, $batch11$Loux probably wouldn't have objected to Zembaty selling Stoke Farm instead of giving it to the grandson.$batch11$), (1, $batch11$Evidence$batch11$, $batch11$Loux never expressed any desire about Stoke Farm, the only farmland in the estate. Loux was very fond of the grandson, the only beneficiary.$batch11$), (2, $batch11$Evaluate$batch11$, $batch11$The argument treats Loux's silence as indifference. But Loux was fond of the grandson. If the grandson wanted a farm, Loux may have cared about Stoke Farm going to the grandson without ever saying so.$batch11$), (3, $batch11$Goal$batch11$, $batch11$Give Loux a reason to want Stoke Farm kept for the grandson.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT112-S3-Q5$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$If the farm had to be sold to clear the debts, Loux would be even less likely to object.$batch11$), ($batch11$B$batch11$, $batch11$Taking care of the grandson could be done with any part of the estate.$batch11$), ($batch11$C$batch11$, $batch11$Knowing the executor's legal duties doesn't show any preference about the farm.$batch11$), ($batch11$D$batch11$, $batch11$If the farm caused the debts, selling it makes even more sense.$batch11$), ($batch11$E$batch11$, $batch11$Loux was fond of the grandson, who wanted a farm, and Stoke Farm was the only farmland. Loux plausibly would have wanted it kept.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT112-S3-Q5$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
